Definition inv (Mi : word -> option byte) (mdi : Model) (cri : credit) (ki : PESK.sink) (a : Z) : Prop :=
  L5.u64_at RSEGS Mi (sp - 8) (bv_unsigned (getr R (PMK.reg 1))) /\ L5.u64_at RSEGS Mi (sp - 16) (bv_unsigned (getr R (PMK.reg 8)))
  /\ L5.u64_at RSEGS Mi (sp - 24) (bv_unsigned (getr R (PMK.reg 9)))
  /\ L5C.stk (hl_sptop L) Mi sp 18432 /\ model_but_vm model mdi /\ PMSP.model_ok mdi
  /\ hi_heap HI (PESK.sink_own ki ++ LBF) cri Mi (m_vmmaps mdi)
  /\ PESK.sink_at RSEGS L PMSP.T3 PMSP.T4 P Mi (fb + 488) ki
  /\ xlo + a <= PESK.sk_z ki <= xhi + a
  /\ PMK.ek L LBF sp 18432 Ws M Mi /\ PMK.dk L LBF sp 18432 M Mi
  /\ PMSP.credit_keep cr cri (PEC.pot_enc L P en k) (PEC.pot_enc L P en ki).

